const body = $input.first().json.body || $input.first().json;
const source = body.source || 'chatgpt';
const title = body.title || 'Untitled capture';
const content = body.content || '';
const typeHint = body.type_hint || '';

const now = new Date();
const date = now.toISOString().slice(0, 10);
const time = now.toISOString().slice(11, 19);

const slug = title
  .toLowerCase()
  .replace(/[^a-z0-9\s-]/g, '')
  .trim()
  .replace(/\s+/g, '-')
  .slice(0, 40);
const filename = `${date}-${slug}.md`;
const filepath = `01-inbox/${filename}`;

// Build Gemini classification prompt
const promptText = [
  'You are processing a captured note for a personal knowledge management system using the PARA method.',
  '\n\nPARA definitions:',
  '\n- project: has a clear finish line (SaaS app, automation, specific deliverable)',
  '\n- area: ongoing responsibility, no end date (health, finance, business, personal development, ministry)',
  '\n- resource: reference material, research, learning, frameworks, how-to knowledge',
  '\n- inbox: unclear, mixed, needs more context',
  '\n\nContext about the owner:',
  '\n- Builds SaaS apps and business automations',
  '\n- Manages prochattools business (statuslink, xgrow, prochat, says-the-bible, probot)',
  '\n- Has Yeshua Academy (ministry work)',
  '\n- Goal: automate everything, optimise costs, work efficiently',
  `\n\nTitle hint: ${title}`,
  typeHint ? `\nType hint: ${typeHint}` : '',
  `\n\nContent to classify:\n${content}`,
  '\n\nRespond ONLY with valid JSON (no markdown fences, no extra text):\n{\n  "title": "concise title max 6 words",\n  "para_type": "project|area|resource|inbox",\n  "confidence": 0.0,\n  "area_hint": "which life or business area",\n  "tags": ["tag1", "tag2"],\n  "summary": "2-3 sentence summary of the key insight or decision",\n  "key_points": ["point 1", "point 2", "point 3"],\n  "action_items": ["actionable task if any"],\n  "note_content": "full structured markdown body for the note, without frontmatter"\n}'
].join('');

const geminiBody = JSON.stringify({
  contents: [{ parts: [{ text: promptText }] }]
});

// Raw unprocessed file content
const rawFile = [
  '---',
  'type: capture',
  `source: ${source}`,
  `title: "${title}"`,
  `created: ${date}T${time}Z`,
  'status: unprocessed',
  'para_type: null',
  'confidence: null',
  'tags:',
  '  - needs-review',
  '---',
  '',
  `# ${title}`,
  '',
  '## Raw Content',
  content,
  '',
  '---',
  `*Captured ${date}T${time}Z from ${source} — awaiting Gemini classification*`
].join('\n');

return [{
  json: {
    filepath,
    filename,
    rawFile,
    title,
    source,
    content,
    typeHint,
    geminiBody,
    date
  }
}];

const buildData = $('Build Raw File').first().json;
console.log(`[brain-inbox] Gemini failed for ${buildData.filepath} — raw file is safe, retry scheduled job will pick it up`);
return [];

const geminiResponse = $input.first().json;
const buildData = $('Build Raw File').first().json;

const rawText = geminiResponse?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!rawText) {
  // Unexpected Gemini response shape — bail out silently
  return [];
}

// Strip markdown code fences
const stripped = rawText
  .replace(/^```json\s*/m, '')
  .replace(/^```\s*/m, '')
  .replace(/\s*```$/m, '')
  .trim();

// Sanitize literal control chars inside JSON string values
function sanitizeJsonString(str) {
  let result = '';
  let inString = false;
  let escaped = false;
  for (let i = 0; i < str.length; i++) {
    const c = str[i];
    if (escaped) { result += c; escaped = false; }
    else if (c === '\\' && inString) { result += c; escaped = true; }
    else if (c === '"') { result += c; inString = !inString; }
    else if (inString && c === '\n') { result += '\\n'; }
    else if (inString && c === '\r') { result += '\\r'; }
    else if (inString && c === '\t') { result += '\\t'; }
    else if (inString && c.charCodeAt(0) < 32) {
      result += '\\u' + c.charCodeAt(0).toString(16).padStart(4, '0');
    } else { result += c; }
  }
  return result;
}

let parsed;
try {
  parsed = JSON.parse(sanitizeJsonString(stripped));
} catch (e) {
  // JSON parse failed — leave raw file unprocessed
  console.log(`[brain-inbox] JSON parse failed for ${buildData.filepath}: ${e.message}`);
  return [];
}

const date = buildData.date;
const source = buildData.source;

const tagsYaml = (parsed.tags || ['capture'])
  .map(t => `  - ${t}`).join('\n');

const frontmatter = [
  '---',
  'type: capture',
  `source: ${source}`,
  `title: "${parsed.title || buildData.title}"`,
  `para_type: ${parsed.para_type || 'inbox'}`,
  `confidence: ${parsed.confidence ?? 0}`,
  `area: ${parsed.area_hint || ''}`,
  `created: ${date}`,
  'status: processed',
  'tags:',
  tagsYaml,
  '---'
].join('\n');

const keyPoints = (parsed.key_points || []).map(p => `- ${p}`).join('\n') || '-';
const actionItems = (parsed.action_items || []).map(a => `- [ ] ${a}`).join('\n');
const confidence = Math.round((parsed.confidence ?? 0) * 100);

const noteBody = [
  frontmatter,
  '',
  `# ${parsed.title || buildData.title}`,
  '',
  '## Summary',
  parsed.summary || '',
  '',
  '## Key Points',
  keyPoints,
  '',
  actionItems ? `## Action Items\n${actionItems}\n` : '',
  '## Notes',
  parsed.note_content || '',
  '',
  '---',
  `*${source} capture · ${date} · ${confidence}% confidence · suggested: ${parsed.para_type}*`,
  `*Review in [[home|Command Center]] — promote to [[notes/projects/|projects]], [[notes/areas/|areas]], or [[notes/resources/|resources]]*`
].join('\n');

return [{
  json: {
    filepath: buildData.filepath,
    filename: buildData.filename,
    classifiedContent: noteBody,
    title: parsed.title || buildData.title,
    para_type: parsed.para_type,
    confidence: parsed.confidence
  }
}];

const classified = $('Build Classified Note').first().json;
const fileInfo = $input.first().json;
const sha = fileInfo.sha;
if (!sha) {
  throw new Error(`SHA missing for ${classified.filepath} — GitHub response keys: ${Object.keys(fileInfo).join(',')}`);
}
// Base64 encode the classified content for GitHub API
const contentBase64 = Buffer.from(classified.classifiedContent, 'utf8').toString('base64');
return [{
  json: {
    filepath: classified.filepath,
    title: classified.title,
    para_type: classified.para_type,
    confidence: classified.confidence,
    putBody: JSON.stringify({
      message: `brain: classified — ${classified.title} (${classified.para_type})`,
      content: contentBase64,
      sha
    })
  }
}];
